// CheckerFunc adapts a function to ReferrerChecker.
type CheckerFunc func(ctx context.Context, resourceType, name string) ([]Referrer, error)

// Referrers calls f.
func (f CheckerFunc) Referrers(ctx context.Context, resourceType, name string) ([]Referrer, error) {
	return f(ctx, resourceType, name)
}

