// References is the registry the generated repositories enforce reference
// integrity through: resolvers by target type, referrer checkers by the type
// they answer for, a publisher for NOTIFY events. Build it at startup and put
// it on repox.Conn. A nil *References enforces nothing.
//
//	refs := repox.NewReferences().
//		Resolver("vcard.example.com/Card", repox.GRPCGetResolver(cardsConn, "vcard.v1.Cards/GetCard")).
//		Referrers("freebusy.example.com/Resource", repox.ReferenceServiceChecker(storepbv1.NewReferenceServiceClient(bookingConn))).
//		Publisher("//freebusy", webhooks)
//	conn := repox.Conn{Gorm: db, References: refs}
type References struct {
	mu        sync.RWMutex
	resolvers map[string]ReferenceResolver
	checkers  map[string][]ReferrerChecker
	publisher EventPublisher
	source    string
	kept      func(ctx context.Context, name, why string)
	log       *slog.Logger
	warned    sync.Map // resource type -> struct{}: no resolver, warned once
}

// NewReferences returns an empty registry.
func NewReferences() *References {
	return &References{resolvers: map[string]ReferenceResolver{}, checkers: map[string][]ReferrerChecker{}}
}

// Resolver registers how to prove a resource of resourceType exists.
func (r *References) Resolver(resourceType string, rr ReferenceResolver) *References {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.resolvers[resourceType] = rr
	return r
}

// Referrers registers a checker answering who refers to resources of
// resourceType; several may be registered, and every one is asked.
func (r *References) Referrers(resourceType string, c ReferrerChecker) *References {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.checkers[resourceType] = append(r.checkers[resourceType], c)
	return r
}

// Publisher sets where NOTIFY events go and the CloudEvents source they carry.
func (r *References) Publisher(source string, p EventPublisher) *References {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.source, r.publisher = source, p
	return r
}

// OnKept sets f to hear of every row a purge kept because something still
// refers to it, with why ("foreign key", "referrers", "referrers unavailable").
func (r *References) OnKept(f func(ctx context.Context, name, why string)) *References {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.kept = f
	return r
}

// Logger sets the logger warnings go to; slog.Default otherwise.
func (r *References) Logger(l *slog.Logger) *References {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.log = l
	return r
}

func (r *References) logger() *slog.Logger {
	if r != nil && r.log != nil {
		return r.log
	}
	return slog.Default()
}

// Resolve proves the resource name of resourceType exists before a write
// sets field to it. With no resolver registered for the type the write goes
// ahead, after a one-time warning: the check is soft until one is wired.
func (r *References) Resolve(ctx context.Context, field, resourceType, name string) error {
	if r == nil || name == "" {
		return nil
	}
	r.mu.RLock()
	rr := r.resolvers[resourceType]
	r.mu.RUnlock()
	if rr == nil {
		if _, seen := r.warned.LoadOrStore(resourceType, struct{}{}); !seen {
			r.logger().Warn("repox: no ReferenceResolver for a reference type; its references are not checked",
				"resource_type", resourceType, "field", field)
		}
		return nil
	}
	err := rr.Resolve(ctx, resourceType, name)
	if err == nil {
		return nil
	}
	if errors.Is(err, ErrReferenceNotFound) {
		return &ReferenceError{Err: ErrReferenceNotFound, Field: field, ResourceType: resourceType, Name: name, Cause: err}
	}
	return fmt.Errorf("resolve %s %q: %w", resourceType, name, err)
}

// referrers asks every checker for resourceType.
func (r *References) referrers(ctx context.Context, resourceType, name string) ([]Referrer, error) {
	r.mu.RLock()
	cs := r.checkers[resourceType]
	r.mu.RUnlock()
	var out []Referrer
	for _, c := range cs {
		got, err := c.Referrers(ctx, resourceType, name)
		if err != nil {
			return nil, fmt.Errorf("referrers of %s %q: %w", resourceType, name, err)
		}
		out = append(out, got...)
	}
	return out, nil
}

// DeleteCheck is a delete CheckDelete let through; Done publishes its NOTIFY
// event once the delete has happened. A nil *DeleteCheck does nothing.
type DeleteCheck struct {
	refs         *References
	resourceType string
	name         string
	notify       []Referrer
}

// CheckDelete consults the referrers of name before it is deleted: any
// ON_DELETE_RESTRICT referrer refuses the delete with ErrReferenced, and a
// checker that cannot answer fails it (a refusal cannot be proven absent).
func (r *References) CheckDelete(ctx context.Context, resourceType, name string) (*DeleteCheck, error) {
	if r == nil {
		return nil, nil
	}
	all, err := r.referrers(ctx, resourceType, name)
	if err != nil {
		return nil, err
	}
	var restrict, notify []Referrer
	for _, ref := range all {
		switch ref.OnDelete {
		case OnDeleteRestrict:
			restrict = append(restrict, ref)
		case OnDeleteNotify:
			notify = append(notify, ref)
		}
	}
	if len(restrict) > 0 {
		return nil, &ReferenceError{Err: ErrReferenced, ResourceType: resourceType, Name: name, Referrers: restrict}
	}
	return &DeleteCheck{refs: r, resourceType: resourceType, name: name, notify: notify}, nil
}

// Done publishes EventTypeReferenceDeleted for the NOTIFY referrers, if any
// and if a publisher is set. purged says whether the row is gone for good.
// A publish failure is logged, never returned: the delete has happened.
func (c *DeleteCheck) Done(ctx context.Context, purged bool) {
	if c == nil || len(c.notify) == 0 {
		return
	}
	r := c.refs
	r.mu.RLock()
	pub, source := r.publisher, r.source
	r.mu.RUnlock()
	if pub == nil {
		r.logger().Warn("repox: ON_DELETE_NOTIFY referrers but no Publisher; no event sent",
			"resource_type", c.resourceType, "name", c.name, "referrers", len(c.notify))
		return
	}
	data := referencedResourceDeleted{Target: c.name, TargetType: c.resourceType, Purged: purged}
	for _, ref := range c.notify {
		data.Referrers = append(data.Referrers, jsonReferrer{Referrer: ref.Name, ResourceType: ref.ResourceType, Field: ref.Field, OnDelete: ref.OnDelete.String()})
	}
	b, err := json.Marshal(data)
	if err != nil {
		r.logger().Error("repox: encoding a reference event", "error", err)
		return
	}
	e := CloudEvent{
		SpecVersion:     "1.0",
		ID:              NewULID(),
		Source:          source,
		Type:            EventTypeReferenceDeleted,
		Subject:         c.name,
		Time:            time.Now().UTC(),
		DataContentType: "application/json",
		DataSchema:      "type.googleapis.com/store.v1.ReferencedResourceDeleted",
		Data:            b,
	}
	if err := pub.Publish(ctx, e); err != nil {
		r.logger().Error("repox: publishing a reference event", "error", err, "subject", c.name)
	}
}

// KeepOnPurge reports whether a purge must keep name because a referrer
// still names it -- under any policy: a purge keeps history and never fails
// because of a referrer. A checker that cannot answer keeps the row too.
func (r *References) KeepOnPurge(ctx context.Context, resourceType, name string) bool {
	if r == nil {
		return false
	}
	all, err := r.referrers(ctx, resourceType, name)
	if err != nil {
		r.logger().Warn("repox: keeping a row whose referrers could not be asked", "name", name, "error", err)
		r.Kept(ctx, name, "referrers unavailable")
		return true
	}
	if len(all) > 0 {
		r.Kept(ctx, name, "referrers")
		return true
	}
	return false
}

// Kept reports a row a purge kept to the OnKept observer.
func (r *References) Kept(ctx context.Context, name, why string) {
	if r == nil {
		return
	}
	r.mu.RLock()
	f := r.kept
	r.mu.RUnlock()
	if f != nil {
		f(ctx, name, why)
	}
}

// PurgeResult is what a sweep of expired records did, by record name.
type PurgeResult struct {
	Purged []string // removed for good
	Kept   []string // due, but kept because something still refers to them
}

// ReferrerSource is one external reference field of this process's
// resources, as store.v1.ReferenceService answers for it. The generated
// ReferrerSources functions build them from the repositories.
type ReferrerSource struct {
	ResourceType string   // the referring resource's AIP type
	Field        string   // the reference field
	TargetType   string   // the AIP type the field names
	OnDelete     OnDelete // its (store.v1.reference).on_delete
	// List pages the names of the referring resources, deleted or not, whose
	// Field names target.
	List func(ctx context.Context, target string, pageSize int32, pageToken string) (names []string, next string, err error)
}

// referrerToken is ListReferrerPage's page token: which source, and that
// source's own token.
type referrerToken struct {
	Source int    `json:"s"`
	Token  string `json:"t,omitempty"`
}

// ListReferrerPage serves one page of ListReferrers over sources: those whose
// TargetType is targetType (every one when it is empty), in Field then type
// order, each paged through to the end before the next.
func ListReferrerPage(ctx context.Context, sources []ReferrerSource, targetType, target string, pageSize int32, pageToken string) ([]Referrer, string, error) {
	switch {
	case pageSize <= 0:
		pageSize = 100
	case pageSize > 1000:
		pageSize = 1000
	}
	var srcs []ReferrerSource
	for _, s := range sources {
		if targetType == "" || s.TargetType == targetType {
			srcs = append(srcs, s)
		}
	}
	sort.SliceStable(srcs, func(i, j int) bool {
		if srcs[i].Field != srcs[j].Field {
			return srcs[i].Field < srcs[j].Field
		}
		return srcs[i].ResourceType < srcs[j].ResourceType
	})
	var tok referrerToken
	if pageToken != "" {
		b, err := base64.RawURLEncoding.DecodeString(pageToken)
		if err != nil || json.Unmarshal(b, &tok) != nil || tok.Source < 0 || tok.Source > len(srcs) {
			return nil, "", fmt.Errorf("%w: malformed page_token", ErrInvalidArgument)
		}
	}
	var out []Referrer
	for i := tok.Source; i < len(srcs); i++ {
		s := srcs[i]
		inner := ""
		if i == tok.Source {
			inner = tok.Token
		}
		for {
			names, next, err := s.List(ctx, target, pageSize-int32(len(out)), inner)
			if err != nil {
				return nil, "", err
			}
			for _, n := range names {
				out = append(out, Referrer{Name: n, ResourceType: s.ResourceType, Field: s.Field, OnDelete: s.OnDelete})
			}
			if next == "" {
				break
			}
			if int32(len(out)) >= pageSize {
				return out, encodeReferrerToken(referrerToken{Source: i, Token: next}), nil
			}
			inner = next
		}
		if int32(len(out)) >= pageSize && i+1 < len(srcs) {
			return out, encodeReferrerToken(referrerToken{Source: i + 1}), nil
		}
	}
	return out, "", nil
}

func encodeReferrerToken(t referrerToken) string {
	b, _ := json.Marshal(t)
	return base64.RawURLEncoding.EncodeToString(b)
}

// LocalReferrers is a ReferrerChecker over sources in this process: a
// referring side and its target served by one binary, or a test.
func LocalReferrers(sources ...ReferrerSource) ReferrerChecker {
	return CheckerFunc(func(ctx context.Context, resourceType, name string) ([]Referrer, error) {
		var all []Referrer
		token := ""
		for {
			page, next, err := ListReferrerPage(ctx, sources, resourceType, name, 1000, token)
			if err != nil {
				return nil, err
			}
			all = append(all, page...)
			if next == "" {
				return all, nil
			}
			token = next
		}
	})
}

// StoredReference is one reference a reconciler checks: the referring
// record, the field, and the resource it names.
type StoredReference struct {
	Name         string // the referring record's name
	Field        string
	ResourceType string // the named resource's type
	Target       string // the named resource's name
}

// ReconcileOptions tunes a reconciler run.
type ReconcileOptions struct {
	// PageSize is how many records one read takes; 0 means 100.
	PageSize int32
	// SampleSize caps ReconcileReport.Sample; 0 means 20.
	SampleSize int
	// OnDangling hears of every dangling reference (a metric, a log line, a
	// repair queue).
	OnDangling func(ctx context.Context, d StoredReference)
}

// ReconcileReport is what a reconciler run found.
type ReconcileReport struct {
	Checked   int               // references resolved
	Dangling  int               // references whose target's Get said NOT_FOUND
	Unchecked int               // references of a type with no resolver
	Sample    []StoredReference // up to SampleSize dangling references
}

// Reconcile pages every stored reference through page and resolves each with
// the registry's AIP Get resolvers, reporting the ones whose target is gone.
// A resolver error other than not-found stops the run with it.
func Reconcile(ctx context.Context, refs *References, opts ReconcileOptions, page func(ctx context.Context, pageSize int32, token string) ([]StoredReference, string, error)) (ReconcileReport, error) {
	var rep ReconcileReport
	if opts.PageSize <= 0 {
		opts.PageSize = 100
	}
	if opts.SampleSize <= 0 {
		opts.SampleSize = 20
	}
	if refs == nil {
		return rep, nil
	}
	token := ""
	for {
		got, next, err := page(ctx, opts.PageSize, token)
		if err != nil {
			return rep, err
		}
		for _, sr := range got {
			refs.mu.RLock()
			rr := refs.resolvers[sr.ResourceType]
			refs.mu.RUnlock()
			if rr == nil {
				rep.Unchecked++
				continue
			}
			rep.Checked++
			err := rr.Resolve(ctx, sr.ResourceType, sr.Target)
			switch {
			case err == nil:
			case errors.Is(err, ErrReferenceNotFound):
				rep.Dangling++
				if len(rep.Sample) < opts.SampleSize {
					rep.Sample = append(rep.Sample, sr)
				}
				if opts.OnDangling != nil {
					opts.OnDangling(ctx, sr)
				}
			default:
				return rep, fmt.Errorf("reconcile %s %q: %w", sr.ResourceType, sr.Target, err)
			}
		}
		if next == "" {
			return rep, nil
		}
		token = next
	}
}
